/** E6.22: versioned, immutable rigid visual templates.
 *
 * Procedural art remains an authoring recipe, but its builder runs only on a
 * cache miss. Instances clone cheap scene nodes and share compiled geometry.
 * The cache owns only the geometries explicitly returned by the factory
 * plus geometries generated by its optional rigid compiler pass.
 *
 * Important: materials are never owned/disposed here. Default instances use
 * the same (immutable) template materials; pass resolveMaterial for per-kit,
 * per-finish or Studio-mutable palettes. Never put animated rigs, procedural
 * particles or mutable physics nodes into this cache.
 */
import * as THREE from 'three';
import {compileRigidVisualOwner,
 type VisualCompileOptions} from './fieldwork-model-compiler.ts';

export type StaticVisualBuild=Readonly<{
 root:THREE.Group;
 /** Exactly those source geometries whose lifetime this template owns. */
 ownedGeometries:readonly THREE.BufferGeometry[];
}>;
export type StaticVisualTemplateOptions=Readonly<{
 /** Built once per key, and only for eligible rigid siblings. */
 compile?:boolean;
 compilerOptions?:VisualCompileOptions;
 /** Return caller-owned material (or original immutable palette material). */
 resolveMaterial?:(material:THREE.Material,mesh:THREE.Mesh)=>THREE.Material;
}>;
export type StaticVisualLease=Readonly<{
 root:THREE.Group;
 templateKey:string;
 /** Idempotent; detaches only this instance, not shared template resources. */
 release:()=>void;
}>;
type Entry={
 root:THREE.Group;owned:Set<THREE.BufferGeometry>;
 leases:number;compiled:boolean;retired:boolean;
};
function assertRigidPrototype(root:THREE.Group){
 if(!(root instanceof THREE.Group))
  throw Error('Visual template must be a THREE.Group');
 root.traverse(node=>{
  if(node instanceof THREE.InstancedMesh||
     node instanceof THREE.SkinnedMesh||
     node instanceof THREE.Bone||
     node instanceof THREE.Line||
     node instanceof THREE.Points||
     node instanceof THREE.Sprite||
     node.animations.length>0)
   throw Error('Only rigid visual templates may be cached');
  if(node instanceof THREE.Mesh&&
     (node.morphTargetInfluences?.length||node.customDepthMaterial||
      node.customDistanceMaterial||node.userData.keepSeparate))
   throw Error('Animated or specialized mesh cannot be a reusable rigid template');
 });
}
export class StaticVisualTemplateLibrary{
 private readonly templates=new Map<string,Entry>();
 private readonly retired=new Set<Entry>();
 private builds=0;private hits=0;private evictions=0;
 private readonly maxTemplates:number;
 constructor(maxTemplates=128){
  if(!Number.isInteger(maxTemplates)||maxTemplates<1)
   throw Error('Visual template budget must be a positive integer');
  this.maxTemplates=maxTemplates;
 }
 /** Call with a versioned art recipe key: "window:v3:width=...:style=..." */
 acquire(key:string,build:()=>StaticVisualBuild,
  options:StaticVisualTemplateOptions={}):StaticVisualLease{
  if(!key.trim())throw Error('Visual template key must be nonempty');
  let entry=this.templates.get(key);
  const compile=options.compile===true;
  if(entry&&entry.compiled!==compile)
   throw Error('Visual recipe key must include the compiler version/mode');
  if(!entry){
   const recipe=build();
   assertRigidPrototype(recipe.root);
   const owned=new Set(recipe.ownedGeometries);
   if(compile){
    const result=compileRigidVisualOwner(recipe.root,
     options.compilerOptions);
    if(result.archive){
     // The archive is needed by the reversible authoring compiler, but NOT
     // in the final template. Explicit factory ownership retains the source
     // buffers until this template is disposed, with no per-instance clone.
     recipe.root.remove(result.archive);
     for(const child of recipe.root.children)
      if(child instanceof THREE.Mesh&&
         child.userData.fieldworkCompiledModel)
       owned.add(child.geometry);
    }
   }
   entry={root:recipe.root,owned,leases:0,
    compiled:compile,retired:false};
   this.templates.set(key,entry);this.builds++;
  }else{
   this.hits++;
   // Map insertion order is the LRU order, not geometry creation order.
   this.templates.delete(key);this.templates.set(key,entry);
  }
  entry.leases++;
  // Prefer evicting an idle recipe; if all entries are live, retire the
  // oldest and defer GPU disposal until its last instance releases.
  while(this.templates.size>this.maxTemplates){
   const idle=[...this.templates.entries()].find(([,item])=>
    item.leases===0);
   const evict=idle?.[0]??this.templates.keys().next().value!;
   this.invalidate(evict);this.evictions++;
  }
  const instance=entry.root.clone(true);
  if(options.resolveMaterial)instance.traverse(node=>{
   if(!(node instanceof THREE.Mesh))return;
   if(Array.isArray(node.material))
    throw Error('Rigid template material arrays require explicit recipe slots');
   node.material=options.resolveMaterial!(node.material,node);
  });
  let released=false;
  const selected=entry;
  return {root:instance,templateKey:key,release:()=>{
   if(released)return;
   released=true;
   instance.parent?.remove(instance);
   selected.leases--;
   if(selected.retired&&selected.leases===0)
    this.retireGeometry(selected);
  }};
 }
 /** Drop the cache entry immediately, but defer GPU disposal until the last
  * live instance has released its lease. Subsequent acquire rebuilds fresh. */
 invalidate(key:string):boolean{
  const entry=this.templates.get(key);
  if(!entry)return false;
  this.templates.delete(key);
  entry.retired=true;
  if(entry.leases===0)this.retireGeometry(entry);
  else this.retired.add(entry);
  return true;
 }
 clear():void{
  for(const key of [...this.templates.keys()])this.invalidate(key);
 }
 private retireGeometry(entry:Entry){
  for(const geometry of entry.owned)geometry.dispose();
  entry.owned.clear();
  this.retired.delete(entry);
 }
 /** Scene teardown must treat the returned geometry as shared while the
  * library is in use. Site-owned materials have a separate lifetime. */
 sharedGeometries():ReadonlySet<THREE.BufferGeometry>{
  const geometries=new Set<THREE.BufferGeometry>();
  for(const item of this.templates.values())
   for(const geometry of item.owned)geometries.add(geometry);
  for(const item of this.retired)
   for(const geometry of item.owned)geometries.add(geometry);
  return geometries;
 }
 stats():Readonly<{templates:number;retired:number;
   builds:number;hits:number;evictions:number;leases:number;
   geometries:number;maxTemplates:number}>{
  let leases=0;
  for(const item of this.templates.values())leases+=item.leases;
  for(const item of this.retired)leases+=item.leases;
  return {templates:this.templates.size,retired:this.retired.size,
   builds:this.builds,hits:this.hits,evictions:this.evictions,
   leases,geometries:this.sharedGeometries().size,
   maxTemplates:this.maxTemplates};
 }
}
